"""Bundle engine/ephem.js + engine/sol-engine.js into one classic script (engine/sol-page.js) that defines SOLE,
for inlining into the page and for the page's Web Worker. Mirrors engine/sol-facade.js."""
import os, re, subprocess, sys
H = os.path.dirname(os.path.abspath(__file__)); E = os.path.join(H, "engine")
check = subprocess.run(["node", os.path.join(E, "ship-ephem.mjs"), "--check"])
if check.returncode:
    sys.exit(check.returncode)
eph = open(os.path.join(E, "ephem.js"), encoding="utf-8").read().replace("export default ", "var __EPHEM = ", 1)
eng = open(os.path.join(E, "sol-engine.js"), encoding="utf-8").read()
assert "import " not in eng and "export {" not in eng and "export default" not in eng
eng = re.sub(r"^export (const|function|let|class) ", r"\1 ", eng, flags=re.M)
assert not re.search(r"^export ", eng, flags=re.M)
out = ("// generated by world/bundle.py from engine/ephem.js + engine/sol-engine.js (see engine/CHECK.md)\nvar SOLE = (function(){\n\"use strict\";\n" + eph + "\n" + eng +
       "\ninit(__EPHEM);\nreturn { MU_SUN: MU_SUN, PLACES: placesTable(), EPHEM_RANGE: ephemRange(), sub: sub, propagate: function(r, v, dt){ return propagate(r, v, dt); },"
       " periodDays: function(s){ return periodDays(s); }, placeState: function(id, jd){ return placeState(id, jd); }, stateOf: function(o, jd){ return stateOf(o, jd); },"
       " planRide: function(o, to, opts){ return planRide(o, typeof to === 'string' ? { place: to } : to, opts); }, refly: function(o, opts){ return refly(o, opts); },"
       " isoFromJd: isoFromJd, jdFromIso: jdFromIso, battery: battery, fare: fare, SHIP_CLASSES: SHIP_CLASSES, thrustPoint: thrustPoint, G0: G0 };\n})();\n" + open(os.path.join(E, "sol-missions.js"), encoding="utf-8").read() + "\n" + open(os.path.join(E, "sol-rides.js"), encoding="utf-8").read() + "\nif (typeof module !== 'undefined') module.exports = SOLE;\n")
open(os.path.join(E, "sol-page.js"), "w", encoding="utf-8", newline="\n").write(out); print(len(out))
